/* QuickSight 7c63f6a9-5488-4d57-816a-929fa299e888 */
SELECT "video_url", "title", CAST(PARSE_DATETIME("published", 'yyyy-MM-dd''T''HH:mm:ss''Z''') AS TIMESTAMP) AS "published", "description", "star_rating_count", "star_rating_average", "star_rating_min", "star_rating_max", "views", "year", "month", "day", REPLACE("video_url", 'https://www.youtube.com/watch?v=', 'embed/') AS "youtube_embedded_url"
FROM "AwsDataCatalog"."optimization_data"."aws_feeds_youtube"

